const nacl = tweetnacl();

function hexToBytes(h) { const a = []; for (let i = 0; i < h.length; i += 2) a.push(parseInt(h.substr(i, 2), 16)); return new Uint8Array(a); }

function bytesToHex(b) { return [...b].map(x => x.toString(16).padStart(2, '0')).join(''); }

function identityActive(chain) { return (chain || []).some(r => r.kind === 'key_pin'); }

function firstPinIndex(chain) { for (let i = 0; i < chain.length; i++) if (chain[i].kind === 'key_pin') return i; return -1; }

function pinnedPubkeys(chain) { const m = {}; for (const r of chain || []) if (r.kind === 'key_pin') { try { const p = JSON.parse(r.payload); m[p.actor] = p.pubkey; } catch (e) {} } return m; }

function canonicalSeal(r) { return r.prev_hash + '|' + r.kind + '|' + r.ref + '|' + r.payload; }

function sealSignature(r, signingKeyHex) {
  const seed = hexToBytes(String(signingKeyHex).slice(0, 64));
  const kp = nacl.sign.keyPair.fromSeed(seed);
  const sig = nacl.sign.detached(new TextEncoder().encode(canonicalSeal(r)), kp.secretKey);
  return { sig: bytesToHex(sig), sig_by: bytesToHex(kp.publicKey) };
}

async function sha256hex(s) {
  const d = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(s));
  return [...new Uint8Array(d)].map(b => b.toString(16).padStart(2, '0')).join('');
}

async function linesOf(m) {
  return Object.keys(m).sort().map(p => p + '|' + m[p]).join('\n');
}

async function digestOf(state, uiManifest, codeManifest) {
  const recs = state.records.map(r => r.id + '|' + r.body + '|' + r.created).join('\n');
  const ch = state.chain.map(r => r.id + '|' + r.kind + '|' + r.ref + '|' + r.payload + '|' + r.prev_hash + '|' + r.hash + (r.sig ? '|' + r.sig : '')).join('\n');
  return await sha256hex('RECORDS\n' + recs + '\nCHAIN\n' + ch + '\nUI\n' + await linesOf(uiManifest) + '\nCODE\n' + await linesOf(codeManifest));
}

async function verifyChain(chain) {
  let expected = 'GENESIS', issues = [];
  const SIGNED_KINDS = ['record', 'walkout_marker', 'return'];
  const fpi = firstPinIndex(chain || []);
  const pinned = pinnedPubkeys(chain || []);
  const pinnedSet = Object.values(pinned).join(',');
  for (let i = 0; i < chain.length; i++) {
    const r = chain[i];
    if (r.prev_hash !== expected) issues.push('chain break at ' + r.id);
    const h = await sha256hex(r.prev_hash + '|' + r.kind + '|' + r.ref + '|' + r.payload);
    if (h !== r.hash) issues.push('hash mismatch at ' + r.id);
    if (fpi !== -1 && i > fpi && SIGNED_KINDS.indexOf(r.kind) !== -1) {
      if (!r.sig || !r.sig_by) issues.push('IDENTITY ACTIVE — missing signature at seal ' + r.id);
      else {
        if (pinnedSet.indexOf(r.sig_by) === -1) issues.push('UNKNOWN SIGNER at seal ' + r.id);
        else if (!nacl.sign.detached.verify(new TextEncoder().encode(canonicalSeal(r)), hexToBytes(r.sig), hexToBytes(r.sig_by))) issues.push('SIG INVALID at seal ' + r.id);
      }
    }
    expected = r.hash;
  }
  return { ok: issues.length === 0, issues };
}

async function hashAssets(files) {
  const m = {};
  for (const p of Object.keys(files).sort()) m[p] = await sha256hex(files[p]);
  return m;
}

function activeMarker(chain) {
  let marker = null;
  for (const r of chain) {
    if (r.kind === 'walkout_marker') marker = r;
    else if (r.kind === 'return') marker = null;
  }
  return marker;
}

async function canWrite(state) {
  const marker = activeMarker(state.chain || []);
  if (!marker) return { ok: false, reason: 'WRITES SEALED — no active walkout marker (v0.9)' };
  return { ok: true, mode: 'walkout', marker: marker.hash };
}

async function appendWithSeal(state, uiManifest, codeManifest, body, created, actor, signingKeyHex) {
  const cw = await canWrite(state);
  if (!cw.ok) return { ok: false, reason: cw.reason };
  if (!body || !created) return { ok: false, reason: 'body and created required' };
  const lastRec = state.records.length ? state.records[state.records.length - 1] : { id: 0 };
  const id = (Number(lastRec.id) || 0) + 1;
  const rec = { id, body: String(body).slice(0, 300), created: String(created) };
  const tip = state.chain.length ? state.chain[state.chain.length - 1].hash : 'GENESIS';
  const payload = JSON.stringify({ id, body: rec.body, created: rec.created, actor: String(actor || 'stranger') });
  const hash = await sha256hex(tip + '|record|' + id + '|' + payload);
  const seal = { id: state.chain.length + 1, kind: 'record', ref: String(id), payload, prev_hash: tip, hash };
  if (identityActive(state.chain)) {
    if (!signingKeyHex) return { ok: false, reason: 'IDENTITY ACTIVE — sealed write requires a signing key' };
    const sg = sealSignature(seal, signingKeyHex);
    seal.sig = sg.sig; seal.sig_by = sg.sig_by;
  }
  const newState = { records: state.records.concat([rec]), chain: state.chain.concat([seal]) };
  return { ok: true, record: rec, seal, state: newState, digest: await digestOf(newState, uiManifest, codeManifest) };
}

async function ingestReturn(sourceState, uiManifest, codeManifest, survivorExport) {
  const fail = (verdict) => ({ ok: false, verdict });
  const ANCHOR_URLS = ['https://raw.githubusercontent.com/rabiuhamza11/harz-survivor/main/anchors/ledger.md', 'https://cdn.jsdelivr.net/gh/rabiuhamza11/harz-survivor@main/anchors/ledger.md', 'https://raw.githack.com/rabiuhamza11/harz-survivor/main/anchors/ledger.md'];
  if (!survivorExport || !survivorExport.state) return fail('BROKEN — malformed survivor export');
  const sChain = survivorExport.state.chain || [];
  const marker = activeMarker(sChain);
  if (!marker) return fail('BROKEN — no active walkout marker in survivor export');
  const srcChain = sourceState.chain || [];
  let mi = -1;
  for (let i = 0; i < srcChain.length; i++) if (srcChain[i].hash === marker.hash) { mi = i; break; }
  if (mi === -1) return fail('BROKEN — marker mismatch: not my walkout');
  const postMarker = srcChain.slice(mi + 1);
  const bookSeals = postMarker.filter(s => s.kind !== 'code_pin' && s.kind !== 'ui_manifest');
  if (bookSeals.length) return fail('FORK DETECTED — source has post-marker book seals');
  const baseRecords = sourceState.records || [];
  const allRecords = survivorExport.state.records || [];
  if (allRecords.length < baseRecords.length) return fail('BROKEN — base records missing');
  for (let i = 0; i < baseRecords.length; i++) {
    const a = baseRecords[i], b = allRecords[i];
    if (String(a.id) !== String(b.id) || a.body !== b.body || a.created !== b.created)
      return fail('BROKEN — base records rewritten');
  }
  let mIdx = -1;
  for (let i = 0; i < sChain.length; i++) if (sChain[i].hash === marker.hash) { mIdx = i; break; }
  const overlay = sChain.slice(mIdx + 1);
  const overlayRecords = allRecords.slice(baseRecords.length);
  const composed = srcChain.slice(0, mi + 1).concat(overlay);
  const v = await verifyChain(composed);
  if (!v.ok) return fail('BROKEN — overlay does not chain from the marker: ' + v.issues.join('; '));
  const baseDigest = await digestOf(sourceState, uiManifest, codeManifest);
  let ledger = null, servedFrom = null, anyReachable = false;
  for (const u of ANCHOR_URLS) {
    try {
      const res = await fetch(u, { cache: 'no-store' });
      if (!res.ok) continue;
      const text = await res.text();
      anyReachable = true;
      if (text.includes(baseDigest)) { ledger = text; servedFrom = u; break; }
    } catch (e) { continue; }
  }
  if (!anyReachable) return fail('BROKEN — ANCHOR UNREACHABLE — return refused fail-closed (all mirrors)');
  if (!ledger) return fail('BROKEN — ANCHOR MISMATCH — pre-marker base ' + baseDigest.slice(0, 16) + '… not found in any reachable anchored history');
  const anchorProof = { url: servedFrom, anchored_base: baseDigest, mirrors_tried: ANCHOR_URLS.length };
  const tip = composed.length ? composed[composed.length - 1].hash : 'GENESIS';
  const payload = JSON.stringify({ ingested_seals: overlay.length, ingested_records: overlayRecords.length, marker: marker.hash, anchor: anchorProof });
  const rhash = await sha256hex(tip + '|return|walkout|' + payload);
  const returnSeal = { id: composed.length + 1, kind: 'return', ref: 'walkout', payload, prev_hash: tip, hash: rhash };
  const newState = { records: baseRecords.concat(overlayRecords), chain: composed.concat([returnSeal]) };
  return { ok: true, verdict: 'RETURN COMPLETE — one book, one history, anchor-verified', state: newState, ingested: { seals: overlay.length, records: overlayRecords.length }, digest: await digestOf(newState, uiManifest, codeManifest) };
}

async function verifyExport(x) {
  const issues = [];
  if (!x || !x.state || !x.ui_manifest || !x.ui || !x.code_manifest || !x.code || !x.digest)
    return { ok: false, issues: ['malformed export'], verdict: 'BROKEN — malformed export' };
  const chain = x.state.chain || [];
  const v = await verifyChain(chain);
  issues.push(...v.issues);
  let seenMarker = false;
  for (const r of chain) {
    if (r.kind === 'walkout_marker') seenMarker = true;
    else if (r.kind === 'return' && !seenMarker) issues.push('return seal without walkout marker at ' + r.id);
  }
  const uiH = await hashAssets(x.ui);
  for (const p of Object.keys(x.ui_manifest)) {
    if (!x.ui[p]) issues.push('missing ui asset ' + p);
    else if (uiH[p] !== x.ui_manifest[p]) issues.push('ui hash mismatch at ' + p);
  }
  const codeH = await hashAssets(x.code);
  for (const p of Object.keys(x.code_manifest)) {
    if (!x.code[p]) issues.push('missing code asset ' + p);
    else if (codeH[p] !== x.code_manifest[p]) issues.push('code hash mismatch at ' + p);
  }
  const pinnedUi = [...chain].reverse().find(s => s.kind === 'ui_manifest');
  if (!pinnedUi) issues.push('no ui_manifest pin in chain');
  else if (pinnedUi.payload !== JSON.stringify(x.ui_manifest)) issues.push('ui_manifest does not match its chain pin');
  const pinnedCode = [...chain].reverse().find(s => s.kind === 'code_pin');
  if (!pinnedCode) issues.push('no code_pin in chain');
  else if (pinnedCode.payload !== JSON.stringify(x.code_manifest)) issues.push('code_manifest does not match its chain pin');
  const d = await digestOf(x.state, x.ui_manifest, x.code_manifest);
  if (d !== x.digest) issues.push('digest mismatch');
  const ok = issues.length === 0;
  return {
    ok,
    issues,
    digest: d,
    writes: activeMarker(chain) ? 'WALKOUT ACTIVE — sealed writes open' : 'WRITES SEALED — no active walkout marker',
    verdict: ok
      ? 'CAPSULE VERIFIED — chain intact, records sealed, ui sealed, code sealed, digest matches (v0.9)'
      : 'BROKEN — ' + issues.join('; ')
  };
}

function canonical(x) {
  if (x === null || typeof x !== 'object') return JSON.stringify(x);
  if (Array.isArray(x)) return '[' + x.map(canonical).join(',') + ']';
  return '{' + Object.keys(x).sort().map(k => JSON.stringify(k) + ':' + canonical(x[k])).join(',') + '}';
}

async function receiveBundle(input) {
  const b = input && input.bundle, localState = input && input.localState;
  const localUiManifest = input && input.localUiManifest, localCodeManifest = input && input.localCodeManifest;
  if (!b || !localState || !localUiManifest || !localCodeManifest) return { ok: false, verdict: 'REFUSED — malformed receive input', zero_ingest: true };
  const { sig, pub, ...body } = b;
  if (!sig || !pub || !b.payload || !b.payloadHash || !b.claimedDigest || !b.enginePin || !b.id || !b.from)
    return { ok: false, verdict: 'REFUSED — unsigned or malformed bundle', zero_ingest: true };
  // 1. payload integrity
  if (await sha256hex(canonical(b.payload)) !== b.payloadHash)
    return { ok: false, verdict: 'REFUSED — payload hash mismatch', zero_ingest: true };
  // 2. signature — Ed25519 via WebCrypto (portable: Node 20+, Cloudflare, Deno)
  try {
    const key = await crypto.subtle.importKey('spki', Uint8Array.from(atob(pub), c => c.charCodeAt(0)), { name: 'Ed25519' }, true, ['verify']);
    const ok = await crypto.subtle.verify({ name: 'Ed25519' }, key, Uint8Array.from(atob(sig), c => c.charCodeAt(0)), new TextEncoder().encode(canonical(body)));
    if (!ok) return { ok: false, verdict: 'REFUSED — signature invalid', zero_ingest: true };
  } catch (e) { return { ok: false, verdict: 'REFUSED — signature check failed: ' + String(e), zero_ingest: true }; }
  // 3. engine pin — the engine never travels; both seats must hold the same pin
  if (b.enginePin !== localCodeManifest['/engine.js'])
    return { ok: false, verdict: 'REFUSED — engine pin mismatch (local ' + String(localCodeManifest['/engine.js']).slice(0, 8) + ' vs bundle ' + String(b.enginePin).slice(0, 8) + ')', zero_ingest: true };
  // 4. UI manifest parity with my sealed capsule
  if (canonical(b.payload.ui_manifest) !== canonical(localUiManifest))
    return { ok: false, verdict: 'REFUSED — ui manifest mismatch vs local sealed capsule', zero_ingest: true };
  // 5. the received book must verify as a self-consistent capsule, digest claim TRUE
  const v = await verifyExport(b.payload);
  if (!v.ok) return { ok: false, verdict: 'REFUSED — sealed verifyExport: ' + v.verdict, zero_ingest: true };
  if (v.digest !== b.claimedDigest || v.digest !== b.payload.digest)
    return { ok: false, verdict: 'REFUSED — digest claim mismatch', zero_ingest: true };
  // 6. fork check — my composed chain must be a PREFIX of the received chain, AND every
  // local record must be contained byte-identical in the received book (records and seals
  // grow in pairs; both dimensions are checked so no divergence can slip through either)
  const mine = localState.chain, theirs = b.payload.state.chain;
  const mineRec = localState.records, theirsRec = b.payload.state.records;
  if (mine.length > theirs.length || mineRec.length > theirsRec.length)
    return { ok: false, verdict: 'FORK DETECTED — local history is longer than the received book; no silent merge, both books unchanged, owner ruling required', zero_ingest: true };
  for (let i = 0; i < mine.length; i++)
    if (canonical(mine[i]) !== canonical(theirs[i]))
      return { ok: false, verdict: 'FORK DETECTED — local chain diverges from the received book at seal ' + mine[i].id + '; no silent merge, both books unchanged, owner ruling required', zero_ingest: true };
  for (let i = 0; i < mineRec.length; i++)
    if (canonical(mineRec[i]) !== canonical(theirsRec[i]))
      return { ok: false, verdict: 'FORK DETECTED — local records diverge from the received book at record ' + mineRec[i].id + '; no silent merge, both books unchanged, owner ruling required', zero_ingest: true };
  // 7. converged, or adopt with a sealed ingest
  if (mine.length === theirs.length)
    return { ok: true, verdict: 'CONVERGED — byte-identical books, nothing written', digest: v.digest, action: 'none' };
  const tip = theirs[theirs.length - 1].hash;
  const sealPayload = JSON.stringify({ from: b.from, bundle: b.id, claimed: b.claimedDigest, received_records: b.payload.state.records.length, received_seals: theirs.length, ts: b.ts || null });
  const sealHash = await sha256hex(tip + '|mesh_ingest|mesh|' + sealPayload);
  const seal = { id: theirs.length + 1, kind: 'mesh_ingest', ref: 'mesh', payload: sealPayload, prev_hash: tip, hash: sealHash };
  const newState = { records: b.payload.state.records, chain: theirs.concat([seal]) };
  const digest = await digestOf(newState, b.payload.ui_manifest, b.payload.code_manifest);
  return { ok: true, verdict: 'ADOPTED — the book walked in; ingest sealed (one book, one history)', action: 'adopt', state: newState, digest, ingested: { records: b.payload.state.records.length - localState.records.length, seals: theirs.length - mine.length } };
}

// ============ RUNG 2: DETERMINISTIC STATE RECONCILIATION (HarzNet law, Oct 1 2026, owner "Do all and leave 3 later") ============
// mergeBooks: two verified books that worked apart merge into ONE canonical book.
// Law: deterministic (same inputs -> same merged book, any seat, any order), fork detection
// at merge time, explicit verdicts per principle 4 (VERIFIED / CONTRADICTED /
// INSUFFICIENT_EVIDENCE / UNRESOLVED), merge receipts, replay-safe and exactly-once.
// Fail-closed: a contradiction or unresolved base NEVER merges silently.

async function mergeBooks(input) {
  const ea = input && input.exportA, eb = input && input.exportB;
  const uiManifest = input && input.uiManifest, codeManifest = input && input.codeManifest;
  const fail = (verdict, extra) => Object.assign({ ok: false, verdict, zero_merge: true }, extra || {});
  if (!ea || !eb || !uiManifest || !codeManifest)
    return fail('INSUFFICIENT_EVIDENCE — merge needs two exports plus the shared manifests');
  const va = await verifyExport(ea), vb = await verifyExport(eb);
  if (!va.ok) return fail('UNRESOLVED — book A does not verify: ' + va.verdict);
  if (!vb.ok) return fail('UNRESOLVED — book B does not verify: ' + vb.verdict);
  if (canonical(ea.ui_manifest) !== canonical(eb.ui_manifest))
    return fail('UNRESOLVED — ui manifests differ; the books are different capsules');
  if (canonical(ea.code_manifest) !== canonical(eb.code_manifest))
    return fail('UNRESOLVED — code manifests differ (different engine pins); the books are different capsules');
  const A = ea.state, B = eb.state;
  const chA = A.chain || [], chB = B.chain || [];
  const rcA = A.records || [], rcB = B.records || [];
  // --- common ancestor: longest prefix where both books agree, seals and records ---
  let k = 0; while (k < chA.length && k < chB.length && canonical(chA[k]) === canonical(chB[k])) k++;
  let kr = 0; while (kr < rcA.length && kr < rcB.length && canonical(rcA[kr]) === canonical(rcB[kr])) kr++;
  if (k === 0 || kr === 0)
    return fail('UNRESOLVED — no common ancestor: the books share no verified history; owner ruling required');
  const baseChain = chA.slice(0, k), baseRecords = rcA.slice(0, kr);
  const tailA_ch = chA.slice(k), tailB_ch = chB.slice(k);
  const tailA_rc = rcA.slice(kr), tailB_rc = rcB.slice(kr);
  const aTip = chA.length ? chA[chA.length - 1].hash : 'GENESIS';
  const bTip = chB.length ? chB[chB.length - 1].hash : 'GENESIS';
  const baseTip = baseChain.length ? baseChain[baseChain.length - 1].hash : 'GENESIS';
  // --- exactly-once: a merge receipt already naming the OTHER side's tip means this pair merged ---
  for (const [chain, otherTip, mine] of [[chA, bTip, 'A'], [chB, aTip, 'B']])
    for (const s of chain)
      if (s.kind === 'merge_receipt') {
        let p = null; try { p = JSON.parse(s.payload); } catch (e) {}
        if (p && (p.a_tip === otherTip || p.b_tip === otherTip)) {
          const holder = mine === 'A' ? ea : eb;
          return { ok: true, replay: true, verdict: 'VERIFIED — merge already sealed (exactly-once); the receipt naming the other tip is in the book', merge_id: p.merge_id, state: holder.state, digest: holder.digest, ui_manifest: holder.ui_manifest, code_manifest: holder.code_manifest, ui: holder.ui, code: holder.code, zero_merge: true };
        }
      }
  // --- conflict scan (fork detection at merge time). Slot = (id, created).
  // Same slot, different body = the same claimed write with different substance = CONTRADICTED,
  // fail-closed, both books unchanged. Identical duplicates dedup. Everything else merges. ---
  const slotMap = {};
  const conflicts = [];
  for (const [from, tail] of [['A', tailA_rc], ['B', tailB_rc]])
    for (const r of tail) {
      const key = String(r.id) + '|' + String(r.created);
      const c = canonical(r);
      if (slotMap[key] !== undefined && slotMap[key].canonical !== c)
        conflicts.push({ slot: key, from1: slotMap[key].from, from2: from });
      else if (slotMap[key] === undefined) slotMap[key] = { from, canonical: c };
    }
  if (conflicts.length)
    return fail('CONTRADICTED — record slot(s) ' + conflicts.map(c => c.slot).join(', ') + ' written differently on both sides; no silent smoothing, both books unchanged, owner ruling required', { conflicts });
  // --- deterministic order FIRST: the lexicographically smaller tip contributes first.
  // Content decides, not seat identity, not call order. The first side keeps every record;
  // identical duplicates are dropped from the second side only. ---
  const aFirst = aTip < bTip;
  const firstFrom = aFirst ? 'A' : 'B', secondFrom = aFirst ? 'B' : 'A';
  const firstRc = aFirst ? tailA_rc : tailB_rc;
  const secondTailRc = aFirst ? tailB_rc : tailA_rc;
  const firstCh = aFirst ? tailA_ch : tailB_ch, secondCh = aFirst ? tailB_ch : tailA_ch;
  const seenFirst = {}; for (const r of firstRc) seenFirst[String(r.id) + '|' + String(r.created)] = canonical(r);
  const dedupedFromSecond = secondTailRc.filter(r => seenFirst[String(r.id) + '|' + String(r.created)] === canonical(r));
  const secondRc = secondTailRc.filter(r => seenFirst[String(r.id) + '|' + String(r.created)] !== canonical(r));
  // second side's records are re-ided into one numbering; originals stay verbatim in the receipt
  const lastFirstId = firstRc.length ? Number(firstRc[firstRc.length - 1].id) : Number(baseRecords.length ? baseRecords[baseRecords.length - 1].id : 0);
  const reIded = secondRc.map((r, j) => ({ id: lastFirstId + 1 + j, body: r.body, created: r.created }));
  const mergedRecords = baseRecords.concat(firstRc).concat(reIded);
  // --- the merge receipt: merge_id, tips, verdict, and the second side's divergent history verbatim (evidence, never erased) ---
  const mergeId = await sha256hex('merge|' + baseTip + '|' + (aTip < bTip ? aTip + '|' + bTip : bTip + '|' + aTip));
  const receipt = {
    merge_id: mergeId, base_tip: baseTip,
    a_tip: aTip < bTip ? aTip : bTip, b_tip: aTip < bTip ? bTip : aTip,
    verdict: 'VERIFIED',
    second_tail_seals: secondCh, second_records_original: secondRc, re_ided: reIded.length
  };
  const receiptPayload = JSON.stringify(receipt);
  const liveTip = firstCh.length ? firstCh[firstCh.length - 1].hash : baseTip;
  const rHash = await sha256hex(liveTip + '|merge_receipt|merge|' + receiptPayload);
  const receiptSeal = { id: baseChain.length + firstCh.length + 1, kind: 'merge_receipt', ref: 'merge', payload: receiptPayload, prev_hash: liveTip, hash: rHash };
  const mergedChain = baseChain.concat(firstCh).concat([receiptSeal]);
  const newState = { records: mergedRecords, chain: mergedChain };
  const vc = await verifyChain(mergedChain);
  if (!vc.ok) return fail('UNRESOLVED — composed merged chain does not verify: ' + vc.issues.join('; '));
  const digest = await digestOf(newState, uiManifest, codeManifest);
  return {
    ok: true, verdict: 'VERIFIED — deterministic merge complete; receipt sealed, one book, one history',
    merge_id: mergeId, state: newState, digest, receipt: receiptSeal,
    ingested: { records: firstRc.length + reIded.length, deduped: dedupedFromSecond.length },
    zero_merge: false
  };
}

