      if (path === '/api/source') return new Response(ENGINE_SRC, { headers: { 'content-type': 'application/javascript; charset=utf-8' } });
      if (path === '/boundary') return new Response(JSON.stringify(BOUNDARY, null, 1), { headers: { 'content-type': 'application/json' } });
