        const b = await req.json().catch(() => null);
        if (!b || !b.msg_id || !b.status) return j({ ok: false, reason: 'msg_id and status required' }, 400);
        const recipient = String(b.recipient || '');
        const receipt = { msg_id: String(b.msg_id), sender: String(b.sender || 'unknown'),
          recipient_masked: recipient.length > 4 ? '***' + recipient.slice(-4) : recipient,
          route: String(b.route || 'unknown'), carrier: String(b.carrier || 'unknown'), status: String(b.status) };
        const state = await getState(db);
        const id = state.records.length + 1;
        const rec = { id, body: JSON.stringify(receipt, Object.keys(receipt)), created: b.ts || new Date().toISOString() };
        const payload = JSON.stringify(rec, ['id', 'body', 'created']);
        const prev = state.chain[state.chain.length - 1].hash;
        const hash = await E.sha256hex(prev + '|record|' + id + '|' + payload);
        state.chain.push({ id: state.chain.length + 1, kind: 'record', ref: String(id), payload, prev_hash: prev, hash });
        state.records.push(rec);
