        if (/^[0-9a-f]{16,64}$/i.test(q)) seal = state.chain.find(s => s.hash.toLowerCase().startsWith(q.toLowerCase()));
        if (!seal) { rec = state.records.find(r => r.body.includes('"' + q + '"')); if (rec) seal = state.chain.find(s => s.kind === 'record' && s.ref === String(rec.id)); }
        if (!seal && /^[0-9]+$/.test(q)) { rec = state.records.find(r => r.id === Number(q)); if (rec) seal = state.chain.find(s => s.kind === 'record' && s.ref === String(rec.id)); }
        if (!seal || seal.kind !== 'record') return j({ ok: false, reason: 'no sealed receipt matches that id' }, 404);
